package com.library.service.impl; import com.library.common.model.PageResult; import com.library.model.entity.Notice; import com.library.mapper.NoticeMapper; import com.library.service.NoticeService; import org.springframework.stereotype.Service; import java.time.LocalDateTime; import java.util.List;
@Service public class NoticeServiceImpl implements NoticeService { private final NoticeMapper mapper; public NoticeServiceImpl(NoticeMapper mapper){this.mapper=mapper;} public List<Notice> publicList(){return mapper.publicList();} public PageResult<Notice> page(int p,int s){return new PageResult<>(mapper.count(),p,s,mapper.page((p-1)*s,s));} public void save(Notice x){if(x.getPublishStatus()!=null&&x.getPublishStatus()==1)x.setPublishedAt(LocalDateTime.now());mapper.insert(x);} public void update(Notice x){mapper.update(x);} public void delete(Long id){mapper.delete(id);} }
